import { Fragment } from 'react/jsx-runtime';

import {
  StyledBigNumber,
  StyledBigNumberSuffix,
  StyledBigNumberWithSuffix,
  StyledDivider,
} from 'components/BigNumber/BigNumber.styles';
import {
  BigNumberAlignment,
  BigNumberData,
  BigNumberOrientation,
  BigNumberSize,
  BigNumberSpacing,
  BigNumberTrendColors,
} from 'components/BigNumber/types';
import { getTrendDisplayColor } from 'components/BigNumber/utils';
import { Tooltip } from 'components/UI';
import { useTruncationDetection } from 'hooks';
import { StyledBlackTooltipContainer } from 'shared/Styles/misc.styles';

import {
  BigNumberAudienceTargeting,
  BigNumberComparison,
  BigNumberSecondaryInfo,
} from '../';
import {
  StyledBigNumberCenteredSecondaryInfo,
  StyledBigNumberCenteredWrapper,
  StyledBigNumberColumnDivider,
  StyledBigNumberItemContainer,
  StyledBigNumberItemContent,
  StyledBigNumberMainContent,
} from './BigNumberContent.styles';

interface BigNumberContentProps {
  data: BigNumberData[];
  size?: BigNumberSize;
  spacing?: BigNumberSpacing;
  alignment?: BigNumberAlignment;
  orientation?: BigNumberOrientation;
  dataTestId?: string;
  preserveComparisonSpace?: boolean;
  enableTruncation?: boolean;
  trendColors?: BigNumberTrendColors;
}

const buildTooltipText = (item: BigNumberData): string => {
  const parts: string[] = [];

  if (item.bigNumber?.value) {
    parts.push(`${item.bigNumber.value}${item.bigNumber.measure || ''}`);
  }

  if (item.comparison?.number?.value) {
    parts.push(
      `${item.comparison.number.value}${item.comparison.number.measure || ''}`,
    );
  }

  return parts.join(' ');
};

const getBigNumberDisplayColor = (
  item: BigNumberData,
  trendColors?: BigNumberTrendColors,
): string => getTrendDisplayColor(item.bigNumber, trendColors);

interface BigNumberMainContentItemProps {
  item: BigNumberData;
  index: number;
  size?: BigNumberSize;
  preserveComparisonSpace: boolean;
  dataTestId?: string;
  alignment?: BigNumberAlignment;
  trendColors?: BigNumberTrendColors;
}

const BigNumberMainContentItem = ({
  item,
  index,
  size,
  preserveComparisonSpace,
  dataTestId,
  alignment,
  trendColors,
}: BigNumberMainContentItemProps) => {
  const numberValue = item.bigNumber?.value || '';

  const {
    ref: containerRef,
    displayText,
    isTruncated,
  } = useTruncationDetection<HTMLDivElement>(numberValue?.toString() || '', {
    mode: 'dynamic',
  });

  const bigNumberColor = getBigNumberDisplayColor(item, trendColors);

  const tooltipText = buildTooltipText(item);

  const mainContent = (
    <StyledBigNumberMainContent $alignment={alignment} style={{ minWidth: 0 }}>
      {item.bigNumber?.value && (
        <StyledBigNumberWithSuffix ref={containerRef}>
          <StyledBigNumber
            $truncatable
            $size={size}
            style={{ color: bigNumberColor }}
          >
            {displayText}
          </StyledBigNumber>
          {item.bigNumber.measure && (
            <StyledBigNumberSuffix
              $size={size}
              style={{ color: bigNumberColor }}
            >
              {item.bigNumber.measure}
            </StyledBigNumberSuffix>
          )}
        </StyledBigNumberWithSuffix>
      )}
      <BigNumberComparison
        item={item}
        size={size}
        preserveSpace={preserveComparisonSpace}
        alignment={alignment}
        trendColors={trendColors}
        dataTestId={
          dataTestId ? `${dataTestId}-item-${index}-comparison` : undefined
        }
      />

      {item.audience && (
        <BigNumberAudienceTargeting
          item={item}
          dataTestId={
            dataTestId ? `${dataTestId}-item-${index}-audience` : undefined
          }
          audienceType={item.audienceType}
        />
      )}
    </StyledBigNumberMainContent>
  );

  if (isTruncated) {
    return (
      <Tooltip
        content={
          <StyledBlackTooltipContainer>
            {tooltipText}
          </StyledBlackTooltipContainer>
        }
        position="top"
      >
        {mainContent}
      </Tooltip>
    );
  }

  return mainContent;
};

interface BigNumberItemPrimaryContentProps {
  enableTruncation: boolean;
  item: BigNumberData;
  index: number;
  size?: BigNumberSize;
  preserveComparisonSpace: boolean;
  dataTestId?: string;
  alignment?: BigNumberAlignment;
  trendColors?: BigNumberTrendColors;
}

const BigNumberItemPrimaryContent = ({
  enableTruncation,
  item,
  index,
  size,
  preserveComparisonSpace,
  dataTestId,
  alignment,
  trendColors,
}: BigNumberItemPrimaryContentProps) => {
  if (enableTruncation) {
    return (
      <BigNumberMainContentItem
        item={item}
        index={index}
        size={size}
        preserveComparisonSpace={preserveComparisonSpace}
        dataTestId={dataTestId}
        alignment={alignment}
        trendColors={trendColors}
      />
    );
  }

  return (
    <StyledBigNumberMainContent $alignment={alignment}>
      {item.bigNumber?.value && (
        <StyledBigNumber
          $size={size}
          style={{ color: getBigNumberDisplayColor(item, trendColors) }}
        >
          {item.bigNumber.value}
          {item.bigNumber.measure}
        </StyledBigNumber>
      )}
      <BigNumberComparison
        item={item}
        size={size}
        preserveSpace={preserveComparisonSpace}
        alignment={alignment}
        trendColors={trendColors}
        dataTestId={
          dataTestId ? `${dataTestId}-item-${index}-comparison` : undefined
        }
      />

      {item.audience && (
        <BigNumberAudienceTargeting
          item={item}
          dataTestId={
            dataTestId ? `${dataTestId}-item-${index}-audience` : undefined
          }
        />
      )}
    </StyledBigNumberMainContent>
  );
};

export const BigNumberContent = ({
  data,
  size,
  spacing,
  alignment,
  orientation,
  dataTestId,
  preserveComparisonSpace = false,
  enableTruncation = false,
  trendColors,
}: BigNumberContentProps) => {
  const isCenteredVerticalLayout =
    alignment === 'center' &&
    orientation !== 'horizontal' &&
    orientation !== 'none';

  const secondaryInfoItem = isCenteredVerticalLayout
    ? data.find((item) => item.secondaryInfo)
    : undefined;

  const items = (
    <>
      {data.map((item, index) => {
        const shouldRenderDivider =
          orientation != 'horizontal' && index < data.length - 1;

        return (
          <Fragment key={`${item.bigNumber?.value}-${index}`}>
            <StyledBigNumberItemContent
              $spacing={spacing}
              $alignment={alignment}
              $orientation={orientation}
              style={enableTruncation ? { minWidth: 0 } : undefined}
            >
              <BigNumberItemPrimaryContent
                enableTruncation={enableTruncation}
                item={item}
                index={index}
                size={size}
                preserveComparisonSpace={preserveComparisonSpace}
                dataTestId={dataTestId}
                alignment={alignment}
                trendColors={trendColors}
              />

              {!isCenteredVerticalLayout && (
                <BigNumberSecondaryInfo
                  item={item}
                  size={size}
                  dataTestId={
                    dataTestId
                      ? `${dataTestId}-item-${index}-secondary`
                      : undefined
                  }
                />
              )}
            </StyledBigNumberItemContent>
            {shouldRenderDivider &&
              (isCenteredVerticalLayout ? (
                <StyledBigNumberColumnDivider />
              ) : (
                <StyledDivider />
              ))}
          </Fragment>
        );
      })}
    </>
  );

  const container = (
    <StyledBigNumberItemContainer
      className="bigNumberItemContainer"
      $orientation={orientation}
      $alignment={alignment}
      style={
        orientation === 'horizontal'
          ? { gridTemplateColumns: `repeat(${data.length}, 150px)` }
          : undefined
      }
      data-testid={dataTestId ? `${dataTestId}` : undefined}
    >
      {items}
    </StyledBigNumberItemContainer>
  );

  if (!isCenteredVerticalLayout) {
    return container;
  }

  return (
    <StyledBigNumberCenteredWrapper className="bigNumberCenteredWrapper">
      {container}
      {secondaryInfoItem && (
        <StyledBigNumberCenteredSecondaryInfo className="bigNumberCenteredSecondaryInfo">
          <BigNumberSecondaryInfo
            item={secondaryInfoItem}
            size={size}
            dataTestId={
              dataTestId ? `${dataTestId}-centered-secondary` : undefined
            }
          />
        </StyledBigNumberCenteredSecondaryInfo>
      )}
    </StyledBigNumberCenteredWrapper>
  );
};
